public inherited sharing class Application {

    public static fflib_Application.UnitOfWorkFactory UnitOfWork = new UnitOfWorkFactoryImpl();

    public static fflib_Application.SelectorFactory Selector = new SelectorFactoryImpl();

    public static fflib_Application.DomainFactory Domain = getDomainFactory();

    public static fflib_Application.ServiceFactory Service = new ServiceFactoryImpl();

    // ---- Unit of Work: ordered so parents commit before children ----
    private class UnitOfWorkFactoryImpl extends fflib_Application.UnitOfWorkFactory {
        public override fflib_ISObjectUnitOfWork newInstance() {
            return new fflib_SObjectUnitOfWork(new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            });
        }
    }

    // ---- Selector ----
    private class SelectorFactoryImpl extends fflib_Application.SelectorFactory {
        public override fflib_ISObjectSelector newInstance(Schema.SObjectType sObjectType) {
            if (sObjectType == Account.SObjectType) {
                return new AccountsSelector();
            }
            if (sObjectType == Contact.SObjectType) {
                return new ContactsSelector();
            }
            return null;
        }
    }

    // ---- Domain: queries through the Selector factory above ----
    private static fflib_Application.DomainFactory getDomainFactory() {
        fflib_Application.DomainFactory factory = new fflib_Application.DomainFactory(Selector);
        factory.register(Account.SObjectType, new Accounts.Constructor());
        return factory;
    }

    // ---- Service ----
    private class ServiceFactoryImpl extends fflib_Application.ServiceFactory {
        public override Object newInstance(Type serviceType) {
            if (serviceType == IAccountsService.class) {
                return new AccountsServiceImpl();
            }
            return null;
        }
    }
}
