## File: force-app/main/default/classes/CaseSurveyDispatcherJob.cls

```apex
/**
 * Fans out a list of Case Ids into individual CaseSurveyJob Queueable
 * enqueues, respecting the 50-enqueueJob-per-transaction governor limit.
 *
 * Each execution enqueues up to 49 child jobs; if cases remain, it chains
 * itself (consuming the 50th enqueue slot).  Maximum chain depth = 5,
 * which supports up to 49 × 5 = 245 cases in a single trigger firing.
 */
public with sharing class CaseSurveyDispatcherJob implements Queueable {

    private final List<Id> caseIds;
    private final Integer offset;

    // Constructor used on first invocation (offset defaults to 0)
    public CaseSurveyDispatcherJob(List<Id> caseIds) {
        this.caseIds = caseIds;
        this.offset  = 0;
    }

    // Private constructor used when chaining
    private CaseSurveyDispatcherJob(List<Id> caseIds, Integer offset) {
        this.caseIds = caseIds;
        this.offset  = offset;
    }

    public void execute(QueueableContext context) {
        // Process up to 49 cases so we always have a slot left for chaining.
        Integer limit = Math.min(49, caseIds.size() - offset);

        for (Integer i = 0; i < limit; i++) {
            System.enqueueJob(new CaseSurveyJob(caseIds[offset + i]));
        }

        // Chain if there are remaining cases.
        Integer nextOffset = offset + limit;
        if (nextOffset < caseIds.size()) {
            System.enqueueJob(new CaseSurveyDispatcherJob(caseIds, nextOffset));
        }
    }
}
