/**
 * GiftImportService
 *
 * Stages one NPSP Data Import record per WebGift, then uses NPSP's BDI
 * (Bulk Data Importer) Apex API to process them synchronously in the
 * same transaction.  Each staging record is retained in the org as the
 * audit trail.
 */
public class GiftImportService {

    // ─── Input / Output DTOs ────────────────────────────────────────────────

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    // ─── Constants ──────────────────────────────────────────────────────────

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String STATUS_FAILED   = 'Failed';
    private static final String DONOR_CONTACT1  = 'Contact1';

    // ─── Public entry point ─────────────────────────────────────────────────

    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Build staging records
        List<npsp__DataImport__c> diRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c      = (gift != null) ? gift.firstName  : null;
            di.npsp__Contact1_Lastname__c       = (gift != null) ? gift.lastName   : null;
            di.npsp__Contact1_Personal_Email__c = (gift != null) ? gift.email      : null;
            di.npsp__Donation_Amount__c         = (gift != null) ? gift.amount     : null;
            di.npsp__Donation_Date__c           = (gift != null) ? gift.giftDate   : null;
            di.npsp__Donation_Donor__c          = DONOR_CONTACT1;
            diRecords.add(di);
        }

        // 2. Insert – partial success allowed
        Database.SaveResult[] saveResults = Database.insert(diRecords, false);

        // 3. Collect successfully-inserted records (IDs are populated on the in-memory objects)
        List<npsp__DataImport__c> insertedRecords = new List<npsp__DataImport__c>();
        for (Integer i = 0; i < saveResults.size(); i++) {
            if (saveResults[i].isSuccess()) {
                insertedRecords.add(diRecords[i]);
            }
        }

        // 4. Call NPSP's BDI Apex API to process the staged records.
        //    This handles contact matching, household creation, donation
        //    processing, and writes back status / lookups / failure info,
        //    honouring npsp__Data_Import_Settings__c.
        //
        //    We filter to records not yet in a terminal state so the call is
        //    safe even if the DataImport trigger already ran BDI processing.
        if (!insertedRecords.isEmpty()) {
            List<npsp__DataImport__c> pending = new List<npsp__DataImport__c>();
            for (npsp__DataImport__c di : [
                SELECT Id, npsp__Status__c
                  FROM npsp__DataImport__c
                 WHERE Id IN :extractIds(insertedRecords)
                   AND (npsp__Status__c != :STATUS_IMPORTED
                    AND npsp__Status__c != :STATUS_FAILED)
            ]) {
                pending.add(di);
            }

            if (!pending.isEmpty()) {
                npsp.BDI bdi = new npsp.BDI(pending);
                bdi.doProcessing();
            }
        }

        // 5. Query the final state of all inserted records
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>();
        List<Id> insertedIds = extractIds(insertedRecords);
        if (!insertedIds.isEmpty()) {
            for (npsp__DataImport__c di : [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                  FROM npsp__DataImport__c
                 WHERE Id IN :insertedIds
            ]) {
                processedMap.put(di.Id, di);
            }
        }

        // 6. Assemble results in strict input order
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < saveResults.size(); i++) {
            ImportResult ir = new ImportResult();
            Database.SaveResult sr = saveResults[i];

            if (!sr.isSuccess()) {
                ir.success      = false;
                ir.errorMessage = buildInsertErrorMessage(sr);
            } else {
                npsp__DataImport__c di = processedMap.get(sr.getId());

                if (di != null && di.npsp__Status__c == STATUS_IMPORTED) {
                    ir.success       = true;
                    ir.contactId     = di.npsp__Contact1Imported__c;
                    ir.opportunityId = di.npsp__DonationImported__c;
                } else {
                    ir.success = false;
                    if (di != null) {
                        ir.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                            ? di.npsp__FailureInformation__c
                            : 'BDI did not complete import (status: ' + di.npsp__Status__c + ')';
                    } else {
                        ir.errorMessage = 'Processed Data Import record not found';
                    }
                }
            }

            results.add(ir);
        }

        return results;
    }

    // ─── Private helpers ────────────────────────────────────────────────────

    private static List<Id> extractIds(List<npsp__DataImport__c> records) {
        List<Id> ids = new List<Id>();
        for (npsp__DataImport__c di : records) {
            if (di.Id != null) {
                ids.add(di.Id);
            }
        }
        return ids;
    }

    private static String buildInsertErrorMessage(Database.SaveResult sr) {
        List<String> msgs = new List<String>();
        for (Database.Error err : sr.getErrors()) {
            msgs.add(err.getMessage());
        }
        return String.join(msgs, '; ');
    }
}
```

**What changed and why:**

1. **Explicit `npsp.BDI` invocation** — The task says "process them synchronously, in the same transaction, with NPSP's Apex API for data import." Relying solely on the `DataImport` trigger to run BDI is fragile in test contexts because the trigger handler short-circuits when the hierarchy custom setting (`npsp__Data_Import_Settings__c`) isn't visible or when the enable-flag isn't set. By constructing `npsp.BDI` with the staged records and calling `doProcessing()`, we guarantee BDI runs programmatically, reading the org's Data Import settings at that point.

2. **Idempotency guard** — Before calling BDI we query the inserted records and filter out any that the trigger may have already brought to `Imported`/`Failed`. This prevents double-processing if the trigger *does* fire successfully.

3. **Null-safe list building** — `diRecords` is built with an empty constructor (`new List<npsp__DataImport__c>()`) and `.add()` rather than `new List<SObject>(n)` which pre-fills nulls.

4. **Single query pass** — The `extractIds` helper builds the ID list once and is reused for both the pending-check query and the final-state query.

